//! Generated files on disk: written only where their contents change, and deleted
//! where a stack no longer produces them.

use std::fs;
use std::io::{BufRead, BufReader};
use std::path::{Path, PathBuf};

const HEADER_START: &str = "Generated by tfgen";

/// The header a generated file carries, naming what it is generated from.
pub fn header_comment(sources: &[String]) -> String {
    format!("{HEADER_START} from {}. Do not edit.", sources.join(", "))
}

/// What one stack's write changed on disk.
#[derive(Default)]
pub struct DiskChanges {
    pub written: Vec<PathBuf>,
    pub deleted: Vec<PathBuf>,
}

/// Writes `files` where they change, then deletes every file of `directory` that
/// carries tfgen's header and is not among them.
pub fn write_stack_files(
    directory: &Path,
    files: &[(PathBuf, String)],
) -> Result<DiskChanges, String> {
    let mut changes = DiskChanges::default();
    for (path, contents) in files {
        let current = fs::read_to_string(path).ok();
        if current.as_deref() != Some(contents.as_str()) {
            fs::write(path, contents)
                .map_err(|error| format!("writing {}: {error}", path.display()))?;
            changes.written.push(path.clone());
        }
    }
    let listed = fs::read_dir(directory)
        .map_err(|error| format!("reading {}: {error}", directory.display()))?;
    let mut stale = Vec::new();
    for entry in listed.flatten() {
        let path = entry.path();
        if path.is_file()
            && !files.iter().any(|(written, _)| *written == path)
            && carries_header(&path)
        {
            stale.push(path);
        }
    }
    stale.sort();
    for path in stale {
        fs::remove_file(&path).map_err(|error| format!("deleting {}: {error}", path.display()))?;
        changes.deleted.push(path);
    }
    Ok(changes)
}

fn carries_header(path: &Path) -> bool {
    let Ok(file) = fs::File::open(path) else {
        return false;
    };
    let mut first_line = String::new();
    if BufReader::new(file).read_line(&mut first_line).is_err() {
        return false;
    }
    first_line
        .strip_prefix('#')
        .is_some_and(|comment| comment.trim_start().starts_with(HEADER_START))
}

#[cfg(test)]
mod tests {
    use super::*;

    struct ScratchDirectory(PathBuf);

    impl ScratchDirectory {
        fn new(name: &str) -> Self {
            let path = std::env::temp_dir().join(format!("tfgen-{name}-{}", std::process::id()));
            let _ = fs::remove_dir_all(&path);
            fs::create_dir_all(&path).unwrap();
            Self(path)
        }
    }

    impl Drop for ScratchDirectory {
        fn drop(&mut self) {
            let _ = fs::remove_dir_all(&self.0);
        }
    }

    #[test]
    fn only_changed_files_are_written_and_only_tfgen_files_are_deleted() {
        let scratch = ScratchDirectory::new("generated-files");
        let kept = scratch.0.join("main.tf");
        let stale = scratch.0.join("old.tf");
        let hand_written = scratch.0.join("migration.tf");
        let header = format!("# {}\n", header_comment(&["mock.yml".into()]));
        fs::write(&kept, format!("{header}a = 1\n")).unwrap();
        fs::write(&stale, format!("{header}b = 1\n")).unwrap();
        fs::write(&hand_written, "c = 1\n").unwrap();
        let files = vec![(kept.clone(), format!("{header}a = 1\n"))];
        let changes = write_stack_files(&scratch.0, &files).unwrap();
        assert!(changes.written.is_empty());
        assert_eq!(changes.deleted, std::slice::from_ref(&stale));
        assert!(hand_written.exists() && !stale.exists());
    }
}
